function parseHeaderValue(header: string, value: string) {
  if (header === 'x-forwarded-for') {
    return pickFromChain(
      value
        .split(',')
        .map(ip => ip.trim())
        .filter(Boolean),
    );
  }

  if (header === 'forwarded') {
    return pickFromChain(parseForwarded(value));
  }

  return resolveIp(value);
}

