  setError(null);

  try {
    const data = await mutateAsync({ partialToken, token, backupCode });
    setClientAuthToken(data.token);
    setUser(data.user);
    router.push(consumeReturnUrl() ?? '/');
  } catch (err: any) {
    if (err.lockedUntil) {
      setLockUntil(new Date(err.lockedUntil));
    }
    setOtpValue('');
    setError(getErrorMessage(err));
  }
