export function useFilterParameters({
  includePagination = true,
}: {
  includePagination?: boolean;
} = {}) {
  const { pathname, query } = useNavigation();
  const share = useShare();
  const allowFilter = share?.parameters?.allowFilter !== false;
  const isEventsPath = pathname.endsWith('/events');

  return useMemo(() => {
    const filterParams: Record<string, any> = {};

    if (allowFilter) {
      for (const key of Object.keys(query)) {
        const baseName = key.replace(/\d+$/, '');
        if (
          FILTER_COLUMNS[baseName] ||
          /^spf\d+$/.test(key) ||
          (isEventsPath && /^epf\d+$/.test(key))
        ) {
          filterParams[key] = query[key];
        }
      }
    }

    const params = {
      ...filterParams,
      search: query.search,
      segment: allowFilter ? query.segment : undefined,
      cohort: allowFilter ? query.cohort : undefined,
      excludeBounce: allowFilter ? query.excludeBounce : undefined,
      match: allowFilter ? query.match : undefined,
    } as Record<string, any>;

    if (includePagination) {
      params.page = query.page;
      params.pageSize = query.pageSize;
    }

    return params;
  }, [allowFilter, includePagination, isEventsPath, query]);
}

import { formatDate } from '@/lib/date';
import { formatLongNumber } from '@/lib/format';

export function renderNumberLabels(label: string) {
  return +label > 1000 ? formatLongNumber(+label) : label;
}

export function renderDateLabels(unit: string, locale: string) {
  return (label: string, index: number, values: any[]) => {
    const d = new Date(values[index].value);

    switch (unit) {
      case 'minute':
      case 'hour':
        return formatDate(d, 'p', locale);
      case 'day':
        return formatDate(d, 'PP', locale).replace(/\W*20\d{2}\W*/, ''); // Remove year
      case 'month':
        return formatDate(d, 'MMM', locale);
      case 'year':
        return formatDate(d, 'yyyy', locale);
      default:
        return label;
    }
  };
}

export function getChartBucketIndex(data: any[], date: Date) {
  let index = -1;

  for (let i = 0; i < data.length; i++) {
    const timestamp = new Date(data[i]?.x ?? data[i]).getTime();

    if (!Number.isFinite(timestamp)) continue;
    if (timestamp > date.getTime()) break;

    index = i;
  }

  return index;
}

