export function FunnelEditForm({
  id,
  websiteId,
  onSave,
  onClose,
}: {
  id?: string;
  websiteId: string;
  onSave?: () => void;
  onClose?: () => void;
}) {
  const { t, labels } = useMessages();
  const { data, isLoading } = useFunnelDefinitionQuery(websiteId, id);
  const { mutateAsync, error, isPending, touch } = useUpdateQuery(
    `/websites/${websiteId}/funnels${id ? `/${id}` : ''}`,
  );

  const handleSubmit = async ({
    name,
    ...parameters
  }: {
    name: string;
    [key: string]: unknown;
  }) => {
    await mutateAsync(
      { name, description: data?.description, parameters },
      {
        onSuccess: async () => {
          touch('websites:funnels');
          onSave?.();
          onClose?.();
        },
      },
    );
  };

  if (id && isLoading) {
    return <Loading placement="absolute" />;
  }

  const defaultValues = {
    name: data?.name || '',
    window: data?.parameters?.window || 60,
    steps: (data?.parameters?.steps || [{ type: 'path', value: '' }]).map(step => ({
      ...step,
      filters: step.filters || [],
    })),
  };

  return (
    <Form onSubmit={handleSubmit} error={error?.message} defaultValues={defaultValues}>
      <FormField name="name" label={t(labels.name)} rules={{ required: t(labels.required) }}>
        <TextField autoFocus />
      </FormField>
      <FormField
        name="window"
        label={t(labels.window)}
        rules={{
          required: t(labels.required),
          pattern: {
            value: /^[1-9][0-9]*$/,
            message: t(labels.invalidValue) || 'Must be greater than 0',
          },
        }}
      >
        <TextField />
      </FormField>
      <FormFieldArray
        name="steps"
        label={t(labels.steps)}
        rules={{
          validate: value => value.length > 1 || 'At least two steps are required',
        }}
      >
        {({ fields, append, remove }) => {
          return (
            <Grid gap>
              {fields.map(
                ({ id, value: initialEventName }: { id: string; value: string }, index: number) => (
                  <Fragment key={id}>
                    {index > 0 && <ListSeparator />}
                    <StepRow
                      index={index}
                      websiteId={websiteId}
                      initialEventName={initialEventName}
                      onRemove={() => remove(index)}
                    />
                  </Fragment>
                ),
              )}
              <ListSeparator />
              <Row>
                <Button
                  onPress={() => append({ type: 'path', value: '', filters: [] })}
                  isDisabled={fields.length >= FUNNEL_STEPS_MAX}
                >
                  <Icon>
                    <Plus />
                  </Icon>
                  <Text>{t(labels.add)}</Text>
                </Button>
              </Row>
            </Grid>
          );
        }}
      </FormFieldArray>
      <FormButtons style={{ paddingBottom: '16px' }}>
        <Button onPress={onClose} isDisabled={isPending}>
          {t(labels.cancel)}
        </Button>
        <FormSubmitButton>{t(labels.save)}</FormSubmitButton>
      </FormButtons>
    </Form>
  );
}

import { type AnalyticsParameters, serializeAnalyticsQuery } from '@/lib/analytics-query';
import type { ReactQueryOptions } from '@/lib/types';
import { useApi } from '../useApi';
import { useDateParameters } from '../useDateParameters';
import { useFilterParameters } from '../useFilterParameters';
import { useModified } from '../useModified';
import { useTimezone } from '../useTimezone';

export function useAnalyticsQuery<T>(
  path: string,
  params: AnalyticsParameters & Record<string, any>,
  options?: ReactQueryOptions<T>,
) {
  const { get, useQuery } = useApi();
  const { startAt, endAt, timezone, unit } = useDateParameters();
  const { toUtc } = useTimezone();
  const filters = useFilterParameters({ includePagination: false });
  const { modified } = useModified(`websites:${path.split('/')[0]}`);
  const { startDate, endDate, ...rest } = params;
  const query = serializeAnalyticsQuery({
    startAt,
    endAt,
    timezone,
    unit,
    ...filters,
    ...Object.fromEntries(Object.entries(rest).filter(([, value]) => value !== undefined)),
    // Dates arrive as profile-timezone wall-clock times, as useDateRange({ timezone }) returns them.
    ...(startDate != null && { startDate: toUtc(startDate) }),
    ...(endDate != null && { endDate: toUtc(endDate) }),
  });
  return useQuery<T>({
    queryKey: [`websites:${path}`, { websiteId: params.websiteId, ...query, modified }],
    queryFn: () => get(`/websites/${params.websiteId}/${path}`, query),
    enabled: !!params.websiteId,
    ...options,
  });
}

