export function LinkMetricsBar({
  linkId,
}: {
  linkId: string;
  showChange?: boolean;
  compareMode?: boolean;
}) {
  const { timezone } = useTimezone();
  const { isAllTime, hasComparison } = useDateRange({ timezone });
  const { t, labels } = useMessages();
  const { data, isLoading, isFetching, error } = useWebsiteStatsQuery({ websiteId: linkId });

  const { pageviews, visitors, visits, comparison } = data || {};

  const metrics = data
    ? [
        {
          value: visitors,
          label: t(labels.visitors),
          change: visitors - comparison.visitors,
          formatValue: formatLongNumber,
        },
        {
          value: visits,
          label: t(labels.visits),
          change: visits - comparison.visits,
          formatValue: formatLongNumber,
        },
        {
          value: pageviews,
          label: t(labels.views),
          change: pageviews - comparison.pageviews,
          formatValue: formatLongNumber,
        },
      ]
    : null;

  return (
    <LoadingPanel
      data={metrics}
      isLoading={isLoading}
      isFetching={isFetching}
      error={error}
      minHeight="136px"
    >
      <MetricsBar>
        {metrics?.map(({ label, value, prev, change, formatValue, reverseColors }: any) => {
          return (
            <MetricCard
              key={label}
              value={value}
              previousValue={prev}
              label={label}
              change={change}
              formatValue={formatValue}
              reverseColors={reverseColors}
              showChange={!isAllTime && hasComparison}
            />
          );
        })}
      </MetricsBar>
    </LoadingPanel>
  );
}

